with with_gaps as (select *, case when lag(paid_at) over (partition by status order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by status order by paid_at, id) + interval '30' day then 1 else 0 end as is_new_burst from payments), islands as (select *, sum(is_new_burst) over (partition by status order by paid_at, id rows between unbounded preceding and current row) as island_id from with_gaps) select case when is_new_burst >= 1 then 'LARGE' else 'SMALL' end as is_new_burst_tier, min(paid_at) as started_at, round(sum(amount) / nullif(count(case when status = 'FAILED' then 1 end), 0), 2) as amount_per_failed, count(distinct id) as distinct_ids, count(*) filter (where status = 'FAILED') as failed_rows, size(collect_set(status)) as num_status, count(*) as row_count from islands group by case when is_new_burst >= 1 then 'LARGE' else 'SMALL' end having round(sum(amount) / nullif(count(case when status = 'FAILED' then 1 end), 0), 2) < 0
